Program source, as submitted (std-only Rust 2024):
use std::fs;
use std::path::Path;

fn main() {
    let n: u64 = 30;

    // Iterative triangular numbers: T(0) = 0, T(k) = T(k-1) + k.
    let mut prev: u64 = 0;
    let mut sum_t: u64 = 0;
    for k in 1..=n {
        let t_k = prev + k;
        sum_t += t_k;
        prev = t_k;
    }
    let t_n = prev;

    let closed_tri = n * (n + 1) / 2;
    let closed_sum = n * (n + 1) * (n + 2) / 6;

    assert_eq!(t_n, n * (n + 1) / 2);
    assert_eq!(sum_t, n * (n + 1) * (n + 2) / 6);
    assert_eq!(t_n, 465);
    assert_eq!(sum_t, 4960);

    let json = format!(
        r#"{{"n": {}, "triangular_n": {}, "sum_of_first_n_triangular": {}, "closed_form_triangular": {}, "closed_form_sum": {}, "assertions_passed": true}}"#,
        n, t_n, sum_t, closed_tri, closed_sum
    );

    let dir = Path::new("/work/artifacts");
    fs::create_dir_all(dir).expect("failed to create /work/artifacts");
    let path = dir.join("result.json");
    fs::write(&path, json.as_bytes()).expect("failed to write result.json");

    let readback = fs::read_to_string(&path).expect("failed to read back result.json");
    assert_eq!(readback, json);

    println!("{}", json);
}

